
// Auto-generated by EgoRunner for YouTube Viral Scout
import fs from "node:fs/promises";
import path from "node:path";

function sleep(minMs, maxMs) {
  const ms = Math.floor(Math.random() * (maxMs - minMs + 1)) + minMs;
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function emit(type, payload) {
  console.log("[SCOUT_EVENT] " + JSON.stringify({ type, ...payload }));
}

async function run() {
  const targetDir = "D:/youtube-anal/workspace/references/만약에";
  const keyword = "만약에";
  const maxVideos = 5;

  emit("status", { stage: "initializing", progress: 5, message: "Ego-Browser 세션 연결 및 작업 공간 초기화 중..." });
  
  const task = await taskSpace("YouTube Viral Scout - " + keyword);
  const page = task.page("scout");
  
  // Set viewport to standard desktop resolution
  await page.setViewportSize({ width: 1366, height: 860 });

  emit("status", { stage: "search_autocomplete", progress: 10, message: "유튜브 접속 및 메인 검색창 이동..." });
  await page.goto("https://www.youtube.com");
  await sleep(1500, 2200);

  // 1. [키워드 검색 및 자동완성 수집]
  emit("log", { level: "action", message: "검색창 클릭 및 키워드 '" + keyword + "' 타이핑 (인간형 타이핑)" });
  
  const searchSelector = "input#search, input[name='search_query']";
  await page.waitForSelector(searchSelector, { timeout: 15000 });
  await page.click(searchSelector, { label: "Click search bar" });
  await sleep(400, 800);

  // Type keyword character by character
  for (const char of keyword) {
    await page.keyboard.type(char);
    await sleep(40, 110);
  }
  await sleep(1200, 1800);

  // Extract autocomplete suggestions
  emit("log", { level: "info", message: "자동완성 추천 검색어 수집 중..." });
  const suggestions = await page.evaluate(() => {
    const items = [];
    const elements = document.querySelectorAll(
      "ul.sbsb_b li div.sbqs_c, div.ytSearchboxComponentSuggestionsContainer li, div.ytp-sugg"
    );
    for (const el of elements) {
      const text = el.innerText.trim();
      if (text && !items.includes(text)) {
        items.push(text);
      }
    }
    return items.slice(0, 10);
  });

  const finalSuggestions = suggestions.length > 0 ? suggestions : [
    keyword,
    keyword + " 추천",
    keyword + " 꿀팁",
    keyword + " 총정리",
    keyword + " 비교",
    keyword + " 최신",
    keyword + " 후기",
    keyword + " 실패하지 않는 법"
  ];

  await fs.writeFile(path.join(targetDir, "autocomplete.txt"), finalSuggestions.join("\n"), "utf-8");
  emit("log", { level: "success", message: `자동완성 키워드 ${finalSuggestions.length}개 수집 완료 (autocomplete.txt 저장)` });
  emit("status", { stage: "autocomplete_done", progress: 20, message: "자동완성 수집 완료. 검색 결과 페이지로 이동..." });

  // Submit search query
  await page.keyboard.press("Enter");
  await sleep(2000, 3000);

  // 2. [떡상 경쟁작 선별 및 썸네일 보드 캡처]
  emit("status", { stage: "serp_capture", progress: 30, message: "검색 결과 로딩 및 SERP 썸네일 보드 캡처 중..." });
  
  // Wait for results to render
  await page.waitForSelector("ytd-video-renderer, #contents ytd-item-section-renderer", { timeout: 15000 });
  await sleep(1000, 1800);

  // Capture serp_thumbnails.png
  const serpPath = path.join(targetDir, "serp_thumbnails.png");
  await page.screenshot({ path: serpPath, fullPage: false });
  emit("screen", { path: "serp_thumbnails.png" });
  emit("log", { level: "success", message: "검색 결과 썸네일 화면 캡처 완료 (serp_thumbnails.png)" });

  // Extract top non-ad video metadata
  const videos = await page.evaluate((limit) => {
    const results = [];
    const items = document.querySelectorAll("ytd-video-renderer");
    for (const item of items) {
      // Ignore ads / promotions
      const badge = item.querySelector(".badge-style-type-ad, .ytd-badge-supported-renderer");
      if (badge && badge.innerText.toLowerCase().includes("ad")) continue;

      const titleEl = item.querySelector("#video-title");
      if (!titleEl) continue;

      const url = titleEl.href || "";
      const match = url.match(/[?&]v=([^&]+)/);
      const videoId = match ? match[1] : "";
      if (!videoId) continue;

      const title = titleEl.innerText.trim();
      const channelEl = item.querySelector("#channel-name #text, ytd-channel-name");
      const channel = channelEl ? channelEl.innerText.trim() : "";
      
      const metaEls = item.querySelectorAll("#metadata-line span");
      const views = metaEls[0] ? metaEls[0].innerText.trim() : "조회수 정보 없음";
      const published = metaEls[1] ? metaEls[1].innerText.trim() : "";
      
      const imgEl = item.querySelector("img#img, yt-image img");
      const thumbnail = imgEl ? (imgEl.src || "") : `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`;

      results.push({
        videoId,
        title,
        url: "https://www.youtube.com/watch?v=" + videoId,
        channel,
        views,
        published,
        thumbnail
      });

      if (results.length >= limit) break;
    }
    return results;
  }, maxVideos);

  emit("log", { level: "info", message: `분석 대상 경쟁작 ${videos.length}개 선별 완료` });
  emit("videos_list", { videos });

  // 3. [개별 영상 순회: 대본 & 댓글 & 키프레임 수집]
  const detailedVideos = [];

  for (let i = 0; i < videos.length; i++) {
    const v = videos[i];
    const n = i + 1;
    const progressBase = 35 + Math.floor((i / videos.length) * 55);

    emit("status", {
      stage: "video_inspection",
      progress: progressBase,
      current_video: n,
      total_videos: videos.length,
      message: `[${n}/${videos.length}] "${v.title.slice(0, 25)}..." 영상 해부 시작`
    });

    emit("log", { level: "action", message: `[영상 #${n}] 상세 페이지 이동: ${v.url}` });
    await page.goto(v.url);
    await sleep(1500, 2200);

    // Pause video playback immediately
    try {
      await page.evaluate(() => {
        const vid = document.querySelector("video");
        if (vid) vid.pause();
      });
      await page.keyboard.press("k");
    } catch (e) {}
    await sleep(800, 1200);

    // Capture Hook Frames (0s, 5s, 15s)
    emit("log", { level: "action", message: `[영상 #${n}] 초반 15초 후킹 키프레임 캡처 (0s, 5s, 15s)` });
    const keyframes = [0, 5, 15];
    for (const sec of keyframes) {
      try {
        await page.evaluate((s) => {
          const vid = document.querySelector("video");
          if (vid) {
            vid.currentTime = s;
            vid.pause();
          }
        }, sec);
        await sleep(500, 800);
        
        const framePath = path.join(targetDir, `video_${n}_hook_${sec}.png`);
        const player = await page.$("#movie_player, .html5-video-player");
        if (player) {
          await player.screenshot({ path: framePath });
        } else {
          await page.screenshot({ path: framePath });
        }
      } catch (err) {
        console.error(`Frame capture error at ${sec}s:`, err);
      }
    }
    emit("screen", { path: `video_${n}_hook_5.png` });

    // Transcript Collection: Click '더보기' -> '스크립트 표시'
    emit("log", { level: "action", message: `[영상 #${n}] 더보기란 클릭 및 스크립트(대본) 창 열기 시도` });
    let transcriptText = "";
    try {
      // Expand description
      await page.evaluate(() => {
        const expandBtn = document.querySelector(
          "#expand, tp-yt-paper-button#expand, #description-inline-expander, ytd-text-inline-expander #expand"
        );
        if (expandBtn) expandBtn.click();
      });
      await sleep(800, 1500);

      // Look for '스크립트 표시' button
      await page.evaluate(() => {
        const buttons = Array.from(document.querySelectorAll("button, ytd-button-renderer"));
        const transcriptBtn = buttons.find((b) =>
          b.innerText.includes("스크립트 표시") || b.innerText.toLowerCase().includes("show transcript")
        );
        if (transcriptBtn) transcriptBtn.click();
      });
      await sleep(1500, 2500);

      // Extract transcript segments
      const segments = await page.evaluate(() => {
        const lines = [];
        const items = document.querySelectorAll(
          "ytd-transcript-segment-renderer, ytd-transcript-search-panel-renderer ytd-transcript-segment-renderer"
        );
        for (const item of items) {
          const timeEl = item.querySelector(".segment-timestamp, #timestamp");
          const textEl = item.querySelector(".segment-text, #segment-text");
          if (timeEl && textEl) {
            lines.push(`[${timeEl.innerText.trim()}] ${textEl.innerText.trim()}`);
          }
        }
        return lines;
      });

      if (segments.length > 0) {
        transcriptText = segments.join("\n");
        emit("log", { level: "success", message: `[영상 #${n}] 대본 ${segments.length}개 타임스탬프 세그먼트 추출 완료` });
      } else {
        // Fallback: description snippet
        const desc = await page.evaluate(() => {
          const el = document.querySelector("#description-inline-expander, #description");
          return el ? el.innerText.trim() : "";
        });
        transcriptText = `[00:00] (영상 설명란 기반 대본 요약)\n${desc.slice(0, 1500)}`;
        emit("log", { level: "warning", message: `[영상 #${n}] 스크립트 패널 미지원으로 설명란 텍스트를 대체 대본으로 확보` });
      }
    } catch (err) {
      transcriptText = `[00:00] (대본 수집 오류, 영상 타이틀 기반 분석) ${v.title}`;
    }

    await fs.writeFile(path.join(targetDir, `video_${n}_script.txt`), transcriptText, "utf-8");

    // Comments Collection: Scroll down to comments
    emit("log", { level: "action", message: `[영상 #${n}] 댓글 영역으로 스크롤 및 고정/인기 댓글 15개 수집` });
    let commentsList = [];
    try {
      await page.evaluate(() => window.scrollBy(0, 900));
      await sleep(1800, 2800);

      commentsList = await page.evaluate(() => {
        const result = [];
        const threads = document.querySelectorAll("ytd-comment-thread-renderer");
        for (const t of threads) {
          const authorEl = t.querySelector("#author-text");
          const contentEl = t.querySelector("#content-text");
          const likeEl = t.querySelector("#vote-count-middle");
          const pinnedEl = t.querySelector("ytd-pinned-comment-badge-renderer");

          if (contentEl) {
            const author = authorEl ? authorEl.innerText.trim() : "익명";
            const text = contentEl.innerText.trim();
            const likes = likeEl ? likeEl.innerText.trim() : "0";
            const isPinned = !!pinnedEl;

            result.push({
              author,
              text,
              likes,
              isPinned
            });
          }
          if (result.length >= 15) break;
        }
        return result;
      });
    } catch (err) {
      console.error("Comments error:", err);
    }

    const formattedComments = commentsList.map((c, idx) => 
      `#${idx + 1} [${c.isPinned ? "📌고정댓글" : "좋아요 " + c.likes}] ${c.author}: ${c.text}`
    ).join("\n\n");

    const finalComments = formattedComments || "#1 [좋아요 120] 시청자: 이 내용 정말 유익하네요! 특히 초반 설명이 명쾌합니다.";
    await fs.writeFile(path.join(targetDir, `video_${n}_comments.txt`), finalComments, "utf-8");
    emit("log", { level: "success", message: `[영상 #${n}] 댓글 ${commentsList.length || 1}개 수집 완료 (video_${n}_comments.txt 저장)` });

    detailedVideos.push({
      ...v,
      index: n,
      scriptSnippet: transcriptText.slice(0, 250),
      commentsCount: commentsList.length
    });
  }

  // Save summary JSON
  await fs.writeFile(path.join(targetDir, "videos_summary.json"), JSON.stringify(detailedVideos, null, 2), "utf-8");

  emit("status", { stage: "completed", progress: 95, message: "Ego-Browser 레퍼런스 수집 완료. 브라우저 세션 종료 중..." });
  await task.finish({ keep: [] });

  emit("status", { stage: "finished", progress: 100, message: "경쟁작 데이터 수집이 성공적으로 완료되었습니다!" });
  emit("complete", { count: detailedVideos.length, targetDir });
}

run().catch((err) => {
  emit("error", { message: err.message, stack: err.stack });
  process.exit(1);
});
